#!/usr/bin/env python3
"""Verify the self-signed TLS certificate."""

import ssl
import datetime

CERT_PATH = "/app/ssl/server.crt"

try:
    cert = ssl._ssl._test_decode_cert(CERT_PATH)
except FileNotFoundError:
    print(f"ERROR: Certificate not found at {CERT_PATH}")
    exit(1)
except Exception as e:
    print(f"ERROR: Failed to load certificate: {e}")
    exit(1)

subject = cert.get("subject", [])
common_name = None
for attr in subject:
    if attr[0][0] == "commonName":
        common_name = attr[0][1]
        break

not_after = cert.get("notAfter", "Unknown")
try:
    expiry = datetime.datetime.strptime(not_after, "%b %d %H:%M:%S %Y %Z")
    expiry_str = expiry.strftime("%Y-%m-%d")
except ValueError:
    expiry_str = not_after

print(f"Common Name (CN): {common_name}")
print(f"Organization (O):  {cert.get('organizationName', 'N/A')}")
print(f"Expiration Date:   {expiry_str}")

not_before = cert.get("notBefore", "Unknown")
try:
    start = datetime.datetime.strptime(not_before, "%b %d %H:%M:%S %Y %Z")
    print(f"Valid From:        {start.strftime('%Y-%m-%d')}")
except ValueError:
    print(f"Valid From:        {not_before}")

now = datetime.datetime.now(datetime.timezone.utc)
if start.tzinfo is None:
    start = start.replace(tzinfo=datetime.timezone.utc)
if expiry.tzinfo is None:
    expiry = expiry.replace(tzinfo=datetime.timezone.utc)

if now < start:
    print("ERROR: Certificate is not yet valid.")
    exit(1)
if now > expiry:
    print("ERROR: Certificate has expired.")
    exit(1)

print("\nCertificate verification successful")

